// Turn the comma separated list in Configuration into one item per apex domain.
const cfg = $('Configuration').first().json;
const raw = String(cfg.apexDomains || '');

const seen = new Set();
const out = [];

for (const part of raw.split(/[,\s\n]+/)) {
  const apex = part
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/.*$/, '');

  if (!apex || !apex.includes('.')) continue;
  if (seen.has(apex)) continue;

  seen.add(apex);
  out.push({ json: { apex } });
}

if (out.length === 0) {
  throw new Error(
    'No apex domains configured. Open the Configuration node and add at least one domain you own, for example example.com'
  );
}

return out;

// Compare today's certificate transparency snapshot against the hostnames
// already recorded in the Google Sheet. Only names absent from the sheet
// continue, so a hostname is only ever reported once.
const cfg = $('Configuration').first().json;

const ignoreTerms = String(cfg.ignoreSubstrings || '')
  .split(',')
  .map((s) => s.trim().toLowerCase())
  .filter(Boolean);

// --- what the sheet already knows -----------------------------------------
const known = new Set();
for (const row of $('Read Known Subdomains').all()) {
  const h = String(row.json?.hostname ?? '').trim().toLowerCase();
  if (h) known.add(h);
}

// An empty sheet means this is the first run. Everything is written to the
// sheet as a baseline, but nothing is probed and nothing alerts.
const isSeedRun = known.size === 0;

const queued = $('Split Apex Domains').all();
const responses = $input.all();
const runAt = new Date().toISOString();

const out = [];

for (let i = 0; i < responses.length; i++) {
  const apex = String(queued[i]?.json?.apex || '').toLowerCase();
  if (!apex) continue;

  const payload = responses[i].json;
  const body =
    typeof payload === 'string' ? payload : payload.data ?? payload.body ?? '';

  const snapshot = [
    ...new Set(
      String(body)
        .split('\n')
        .map((n) => n.trim().toLowerCase().replace(/^\*\./, '').replace(/\.$/, ''))
        .filter((n) => n && n.endsWith(apex) && !n.includes(' '))
    ),
  ];

  // A failed or empty response must never look like "everything disappeared".
  if (snapshot.length === 0) continue;

  for (const hostname of snapshot) {
    if (known.has(hostname)) continue;
    if (ignoreTerms.some((t) => hostname.includes(t))) continue;

    known.add(hostname);

    out.push({
      json: {
        apex,
        hostname,
        detectedAt: runAt,
        isSeedRun,
        source: 'crt.name certificate transparency index',
      },
    });
  }
}

return out;

// ---------------------------------------------------------------------------
// EXPOSURE POLICY TABLE
// One flat table. Each entry says how acceptable it is for this kind of thing
// to be reachable from the public internet. Edit freely.
//   never     - should not be internet facing at all
//   rarely    - sometimes legitimate, usually a mistake
//   sometimes - normal public surface, still worth recording
// ---------------------------------------------------------------------------
const POLICY = [
  { exposure: 'never', label: 'Administrative or management console',
    terms: ['admin', 'administrator', 'manage', 'manager', 'mgmt', 'console',
            'cpanel', 'whm', 'plesk', 'phpmyadmin', 'adminer', 'webmin',
            'panel', 'cockpit', 'portainer', 'rancher', 'traefik'] },

  { exposure: 'never', label: 'Hypervisor, BMC or out of band management',
    terms: ['esxi', 'vcenter', 'vsphere', 'proxmox', 'pve', 'xen', 'hyperv',
            'idrac', 'ilo', 'ipmi', 'imm', 'bmc', 'kvm', 'openstack',
            'openshift', 'ocp'] },

  { exposure: 'never', label: 'Database or data store',
    terms: ['db', 'database', 'mysql', 'mariadb', 'postgres', 'pgsql', 'psql',
            'mongo', 'redis', 'memcached', 'mssql', 'oracle', 'sql',
            'cassandra', 'clickhouse', 'warehouse', 'dwh', 'etl', 'elastic',
            'opensearch', 'solr'] },

  { exposure: 'never', label: 'Backup, dump or archive endpoint',
    terms: ['backup', 'backups', 'bak', 'dump', 'dumps', 'snapshot', 'restore',
            'archive', 'veeam', 'bacula'] },

  { exposure: 'never', label: 'Source control, CI/CD or artifact registry',
    terms: ['git', 'gitlab', 'gitea', 'gogs', 'jenkins', 'bamboo', 'teamcity',
            'drone', 'circleci', 'argocd', 'argo', 'spinnaker', 'artifactory',
            'nexus', 'registry', 'harbor', 'quay', 'sonar', 'sonarqube',
            'build', 'builds', 'ci', 'cd', 'runner'] },

  { exposure: 'never', label: 'Monitoring, logging or observability stack',
    terms: ['grafana', 'kibana', 'prometheus', 'alertmanager', 'zabbix',
            'nagios', 'icinga', 'cacti', 'graylog', 'splunk', 'loki', 'jaeger',
            'sentry', 'datadog', 'netdata', 'munin', 'observium', 'librenms'] },

  { exposure: 'never', label: 'Secrets, PKI or certificate infrastructure',
    terms: ['vault', 'secrets', 'keys', 'kms', 'hsm', 'pki', 'ca', 'ocsp',
            'crl', 'certsrv', 'consul', 'etcd', 'zookeeper', 'nomad'] },

  { exposure: 'never', label: 'Internal collaboration or knowledge base',
    terms: ['jira', 'confluence', 'wiki', 'intranet', 'internal', 'sharepoint',
            'nextcloud', 'owncloud', 'seafile', 'redmine', 'bugzilla',
            'mantis', 'phabricator', 'zimbra', 'roundcube', 'squirrelmail'] },

  { exposure: 'never', label: 'Business system of record',
    terms: ['sap', 'netsuite', 'workday', 'peoplesoft', 'dynamics', 'erp',
            'payroll', 'finance', 'hris'] },

  { exposure: 'never', label: 'Network attached storage appliance',
    terms: ['synology', 'qnap', 'truenas', 'freenas', 'unraid', 'nas'] },

  { exposure: 'rarely', label: 'Non production or ephemeral environment',
    terms: ['dev', 'development', 'test', 'testing', 'qa', 'uat', 'sit',
            'stage', 'staging', 'sandbox', 'demo', 'preprod', 'preview',
            'beta', 'alpha', 'canary', 'temp', 'tmp', 'scratch', 'poc', 'lab',
            'old', 'legacy', 'deprecated', 'retired', 'bak2', 'corp'] },

  { exposure: 'rarely', label: 'Remote access or network edge device',
    terms: ['vpn', 'sslvpn', 'remote', 'gateway', 'gw', 'firewall', 'fw',
            'pulse', 'anyconnect', 'globalprotect', 'fortigate', 'ipsec',
            'ssh', 'sftp', 'bastion', 'jump', 'jumpbox', 'citrix', 'rdp',
            'rds', 'vnc', 'teamviewer'] },

  { exposure: 'rarely', label: 'Identity or authentication endpoint',
    terms: ['sso', 'auth', 'login', 'signin', 'idp', 'adfs', 'okta', 'saml',
            'oauth', 'oidc', 'keycloak', 'ldap', 'radius', 'identity'] },

  { exposure: 'rarely', label: 'File transfer or shared storage',
    terms: ['ftp', 'ftps', 'tftp', 'webdav', 'files', 'fileshare', 'share',
            'transfer', 'upload', 'uploads', 'download', 'downloads', 'dropbox',
            'minio', 's3', 'bucket', 'storage'] },

  { exposure: 'sometimes', label: 'Public API or developer surface',
    terms: ['api', 'apis', 'graphql', 'gql', 'rest', 'rpc', 'webhook',
            'webhooks', 'developer', 'developers', 'swagger', 'openapi'] },

  { exposure: 'sometimes', label: 'Public content or support surface',
    terms: ['docs', 'doc', 'help', 'support', 'status', 'blog', 'news',
            'careers', 'jobs', 'shop', 'store', 'events', 'community',
            'forum', 'kb', 'learn', 'academy'] },
];

// Preview and per branch deployment patterns, which keywords alone would miss.
const EPHEMERAL_PATTERNS = [
  /^pr-?\d+/i, /^mr-?\d+/i, /^review-/i, /^feature-/i, /^feat-/i,
  /^branch-/i, /^build-/i, /^deploy-/i, /^ci-/i, /-preview$/i, /-staging$/i,
  /^[0-9a-f]{7,12}$/i, /^[a-z0-9]{20,}$/i,
];

// Numbered infrastructure hosts: web01, srv-2, node3, vm12
const INFRA_PATTERN = /^(web|www|srv|server|host|node|vm|app|lb|ns|mx|mail|edge|origin|cache|proxy|db)[-_]?\d{1,3}$/i;

const EXPOSURE_RANK = { never: 3, rarely: 2, sometimes: 1 };
const VERDICT_RANK = { 'Review now': 4, 'Look soon': 3, Informational: 2, Expected: 1 };

function tokenize(hostname, apex) {
  const prefix = hostname.endsWith('.' + apex)
    ? hostname.slice(0, hostname.length - apex.length - 1)
    : hostname;
  return {
    prefix,
    labels: prefix ? prefix.split('.') : [],
    tokens: prefix ? prefix.split(/[.\-_]/).filter(Boolean) : [],
  };
}

function classify(hostname, apex, expectedPrefixes) {
  const { prefix, labels, tokens } = tokenize(hostname, apex);

  // The apex itself, or a name the operator has declared normal.
  const firstLabel = (labels[0] || '').toLowerCase();
  const isExpected =
    prefix === '' || expectedPrefixes.includes(firstLabel) || expectedPrefixes.includes(prefix);

  let policy = null;
  const matched = [];

  // Short terms (ca, db, ci, gw, ns) must match the whole label, optionally
  // with a trailing number, or they fire on any name that happens to start
  // with those letters. Longer terms may match by prefix (dev -> devops).
  const termMatches = (tok, term) =>
    term.length <= 3
      ? new RegExp('^' + term + '\\d*$').test(tok)
      : tok === term || tok.startsWith(term);

  for (const rule of POLICY) {
    const hit = rule.terms.find((term) => tokens.some((tok) => termMatches(tok, term)));
    if (!hit) continue;
    matched.push({ ...rule, hit });
    if (!policy || EXPOSURE_RANK[rule.exposure] > EXPOSURE_RANK[policy.exposure]) {
      policy = { ...rule, hit };
    }
  }

  const ephemeral = EPHEMERAL_PATTERNS.some((re) => re.test(prefix) || labels.some((l) => re.test(l)));
  const infraHost = labels.some((l) => INFRA_PATTERN.test(l));
  const deepNested = labels.length >= 3;

  return {
    prefix, labels, tokens, isExpected, policy, matched,
    ephemeral, infraHost, deepNested,
    unrecognized: !policy && !isExpected && !ephemeral && !infraHost,
  };
}

// ---------------------------------------------------------------------------
const cfg = $('Configuration').first().json;

const expectedPrefixes = String(cfg.expectedPrefixes || '')
  .split(',')
  .map((s) => s.trim().toLowerCase())
  .filter(Boolean);

const out = [];

for (const item of $input.all()) {
  const { hostname, apex } = item.json;
  const c = classify(hostname, apex, expectedPrefixes);

  const notes = [];
  let policyLabel = 'Unrecognized name';
  let exposure = 'unknown';

  if (c.isExpected) {
    policyLabel = 'Declared normal for this organization';
    exposure = 'expected';
    notes.push('Matches your expectedPrefixes list');
  } else if (c.policy) {
    policyLabel = c.policy.label;
    exposure = c.policy.exposure;
    notes.push(c.policy.label + ' (matched "' + c.policy.hit + '")');
  }

  for (const m of c.matched) {
    if (c.policy && m.label === c.policy.label) continue;
    notes.push('Also looks like: ' + m.label);
  }

  if (c.ephemeral) notes.push('Preview, branch or machine generated name');
  if (c.infraHost) notes.push('Numbered infrastructure host');
  if (c.deepNested) notes.push('Deeply nested hostname');
  if (c.unrecognized) notes.push('Name matches nothing known and is not on your expected list');

  // Provisional verdict from the name alone. The probe can only make this
  // stronger, never weaker.
  let verdict = 'Informational';
  if (exposure === 'never') verdict = 'Review now';
  else if (exposure === 'rarely') verdict = 'Look soon';
  else if (exposure === 'expected') verdict = 'Expected';
  else if (c.unrecognized || c.ephemeral || c.infraHost) verdict = 'Look soon';

  out.push({
    json: {
      ...item.json,
      exposurePolicy: exposure,
      policyLabel,
      policyNotes: notes,
      nameVerdict: verdict,
      nameVerdictRank: VERDICT_RANK[verdict],
    },
  });
}

return out;

// Decide which hostnames earn an outbound HTTPS request this run.
// Nothing is dropped: unprobed names still reach the sheet.
const cfg = $('Configuration').first().json;
const probeCap = Math.max(1, Number(cfg.probeCap) || 25);

const items = $input.all();

// On the first run the sheet is empty, so everything is baseline only.
const seedRun = items.some((i) => i.json.isSeedRun === true);

// Anything the policy considers "Expected" does not need a visit.
const eligible = items
  .filter((i) => !seedRun && i.json.exposurePolicy !== 'expected')
  .sort((a, b) => Number(b.json.nameVerdictRank) - Number(a.json.nameVerdictRank))
  .slice(0, probeCap);

const chosen = new Set(eligible.map((i) => i.json.hostname));

return items.map((i) => ({
  json: { ...i.json, willProbe: chosen.has(i.json.hostname) },
}));

// Read the probe response, extract evidence, and settle a rules based verdict.
// Response bodies are read here and thrown away: only the product name, a
// sanitized page title and the matched signals ever leave this node.

// Products that identify themselves regardless of what the hostname is called.
const PRODUCTS = [
  { name: 'Jenkins', pattern: /Dashboard \[Jenkins\]|<title>[^<]*Jenkins/i, exposure: 'never' },
  { name: 'Grafana', pattern: /<title>\s*Grafana|grafana-app|grafanaBootData/i, exposure: 'never' },
  { name: 'Kibana', pattern: /<title>\s*Kibana|kbn-injected-metadata/i, exposure: 'never' },
  { name: 'phpMyAdmin', pattern: /phpMyAdmin/i, exposure: 'never' },
  { name: 'Adminer', pattern: /<title>[^<]*Adminer/i, exposure: 'never' },
  { name: 'Zabbix', pattern: /Zabbix\s|zabbix\.php/i, exposure: 'never' },
  { name: 'Nagios', pattern: /Nagios Core|<title>\s*Nagios/i, exposure: 'never' },
  { name: 'Graylog', pattern: /<title>\s*Graylog/i, exposure: 'never' },
  { name: 'Prometheus', pattern: /<title>\s*Prometheus/i, exposure: 'never' },
  { name: 'Portainer', pattern: /<title>\s*Portainer|portainer\.io/i, exposure: 'never' },
  { name: 'Harbor registry', pattern: /<title>\s*Harbor|harbor-portal/i, exposure: 'never' },
  { name: 'Rancher', pattern: /<title>\s*Rancher/i, exposure: 'never' },
  { name: 'Traefik dashboard', pattern: /<title>\s*Traefik/i, exposure: 'never' },
  { name: 'Proxmox VE', pattern: /Proxmox Virtual Environment/i, exposure: 'never' },
  { name: 'Cockpit', pattern: /<title>[^<]*Cockpit|cockpit-project/i, exposure: 'never' },
  { name: 'GitLab', pattern: /<title>[^<]*GitLab|gitlab-runner/i, exposure: 'never' },
  { name: 'Nexus Repository', pattern: /Nexus Repository Manager/i, exposure: 'never' },
  { name: 'SonarQube', pattern: /<title>\s*SonarQube/i, exposure: 'never' },
  { name: 'Apache Airflow', pattern: /<title>[^<]*Airflow/i, exposure: 'never' },
  { name: 'MinIO Console', pattern: /MinIO Console|<title>\s*MinIO/i, exposure: 'never' },
  { name: 'RabbitMQ Management', pattern: /RabbitMQ Management/i, exposure: 'never' },
  { name: 'Tomcat Manager', pattern: /Apache Tomcat|Tomcat Manager/i, exposure: 'never' },
  { name: 'Jupyter', pattern: /<title>[^<]*Jupyter/i, exposure: 'never' },
  { name: 'Swagger UI', pattern: /swagger-ui|<title>\s*Swagger/i, exposure: 'rarely' },
  { name: 'Unconfigured web server default page',
    pattern: /Welcome to nginx|Apache2 (Ubuntu|Debian) Default Page|IIS Windows Server|<title>\s*It works!/i,
    exposure: 'rarely' },
];

// Third party services that answer for a hostname they no longer serve.
const TAKEOVER = [
  { service: 'Amazon S3', pattern: /NoSuchBucket|The specified bucket does not exist/i },
  { service: 'GitHub Pages', pattern: /There isn't a GitHub Pages site here/i },
  { service: 'Heroku', pattern: /No such app|herokucdn\.com\/error-pages\/no-such-app/i },
  { service: 'Microsoft Azure', pattern: /Web App - Unavailable|404 Web Site not found/i },
  { service: 'Fastly', pattern: /Fastly error: unknown domain/i },
  { service: 'Shopify', pattern: /Sorry, this shop is currently unavailable/i },
  { service: 'Bitbucket', pattern: /Repository not found/i },
  { service: 'Ghost', pattern: /The thing you were looking for is no longer here/i },
  { service: 'Zendesk', pattern: /Help Center Closed/i },
  { service: 'Netlify', pattern: /Not Found - Request ID/i },
  { service: 'Pantheon', pattern: /The gods are wise, but do not know of the site/i },
  { service: 'Read the Docs', pattern: /unknown to Read the Docs/i },
  { service: 'Surge.sh', pattern: /project not found/i },
  { service: 'Tilda', pattern: /Please renew your subscription/i },
];

const VERDICT_RANK = { 'Review now': 4, 'Look soon': 3, Informational: 2, Expected: 1 };

function strongest(a, b) {
  return VERDICT_RANK[a] >= VERDICT_RANK[b] ? a : b;
}

function safeTitle(body) {
  const m = /<title[^>]*>([\s\S]{0,200}?)<\/title>/i.exec(body);
  if (!m) return '';
  return m[1].replace(/\s+/g, ' ').replace(/[<>]/g, '').trim().slice(0, 120);
}

// Rebuild the exact set the IF node sent to the probe, in the same order,
// so probe results line up with their hostnames by index.
const queue = $('Rank and Flag Probe Queue').all().filter((i) => i.json.willProbe === true);
const probes = $input.all();
const checkedAt = new Date().toISOString();

const out = [];

for (let i = 0; i < queue.length; i++) {
  const base = queue[i].json;
  const probe = probes[i]?.json ?? {};

  const failed = probe.error !== undefined || probe.statusCode === undefined;
  const statusCode = failed ? null : Number(probe.statusCode);
  const body = failed ? '' : String(probe.body ?? probe.data ?? '').slice(0, 40000);
  const headers = failed ? {} : probe.headers || {};

  const hdr = (n) => String(headers[n] ?? headers[n.toLowerCase()] ?? headers[n.toUpperCase()] ?? '');

  const signals = [...(base.policyNotes || [])];
  let verdict = base.nameVerdict;
  let product = '';
  let takeover = '';

  const evidence = {
    reachable: !failed,
    statusCode,
    server: hdr('server').slice(0, 60),
    title: failed ? '' : safeTitle(body),
    basicAuth: false,
    loginForm: false,
    directoryListing: false,
  };

  if (failed) {
    signals.push('No HTTPS response, the certificate exists but nothing answered');
    // Nothing is exposed if nothing answers. A name that should never be
    // public still deserves a look, but it is not an active exposure today.
    verdict = base.exposurePolicy === 'never' ? 'Look soon' : 'Informational';
    signals.push('Downgraded because the host is not currently reachable');
  } else {
    const hit = TAKEOVER.find((f) => f.pattern.test(body));
    if (hit) {
      takeover = hit.service;
      signals.push('Dangling ' + hit.service + ' response, check for subdomain takeover');
      verdict = 'Review now';
    }

    const prod = PRODUCTS.find((p) => p.pattern.test(body));
    if (prod) {
      product = prod.name;
      signals.push('Identified as ' + prod.name + ' from the response');
      verdict = strongest(verdict, prod.exposure === 'never' ? 'Review now' : 'Look soon');
    }

    if (/^Basic/i.test(hdr('www-authenticate'))) {
      evidence.basicAuth = true;
      signals.push('HTTP basic authentication exposed on the public internet');
      verdict = strongest(verdict, 'Look soon');
    }

    if (/<input[^>]+type=["']?password/i.test(body)) {
      evidence.loginForm = true;
      signals.push('Login form served to unauthenticated visitors');
    }

    if (/<title[^>]*>\s*Index of \//i.test(body) || /Directory listing for/i.test(body)) {
      evidence.directoryListing = true;
      signals.push('Directory listing enabled');
      verdict = 'Review now';
    }

    if (statusCode >= 200 && statusCode < 300) {
      signals.push('Answers unauthenticated HTTPS requests (HTTP ' + statusCode + ')');
      // Something that should never be public, and is serving content, is the
      // clearest case there is.
      if (base.exposurePolicy === 'never') verdict = 'Review now';
      else if (evidence.loginForm) verdict = strongest(verdict, 'Look soon');
    } else if (statusCode === 401 || statusCode === 403) {
      signals.push('Access control sits in front of this host (HTTP ' + statusCode + ')');
    } else if (statusCode >= 500) {
      signals.push('Server error response (HTTP ' + statusCode + ')');
      verdict = strongest(verdict, 'Look soon');
    }
  }

  const why =
    failed ? base.policyLabel + ' has a certificate but nothing is answering on it today'
    : product ? product + ' reachable at a hostname that is not on your expected list'
    : takeover ? 'Points at ' + takeover + ' but that service no longer serves this name'
    : base.exposurePolicy === 'never' ? base.policyLabel + ' reachable from the public internet'
    : base.exposurePolicy === 'rarely' ? base.policyLabel + ' visible publicly'
    : signals[0] || 'New hostname observed in certificate transparency';

  const action =
    takeover ? 'Remove the DNS record or reclaim the ' + takeover + ' resource before someone else does'
    : failed ? 'Confirm the certificate is not still valid for something you no longer run'
    : verdict === 'Review now' ? 'Confirm this is meant to be public. If not, put it behind SSO or the VPN today'
    : verdict === 'Look soon' ? 'Identify the owner and confirm the exposure is intentional'
    : 'No action needed, recorded for the inventory';

  out.push({
    json: {
      first_seen: base.detectedAt,
      apex: base.apex,
      hostname: base.hostname,
      verdict,
      why,
      recommended_action: action,
      exposure_policy: base.exposurePolicy,
      risk_score: VERDICT_RANK[verdict] * 25 - (evidence.reachable ? 0 : 10),
      probed: 'yes',
      http_status: failed ? '' : statusCode,
      server: evidence.server,
      page_title: evidence.title,
      product_detected: product,
      takeover_service: takeover,
      analyst: 'rules',
      last_checked: checkedAt,
      // carried for the AI node and the digest, ignored by the sheet mapping
      verdict_rank: VERDICT_RANK[verdict],
      signals,
      evidence,
      policyLabel: base.policyLabel,
    },
  });
}

return out;

// Hostnames that were not probed still belong in the inventory sheet.
// Give them the same column shape as the probed branch.
const VERDICT_RANK = { 'Review now': 4, 'Look soon': 3, Informational: 2, Expected: 1 };
const checkedAt = new Date().toISOString();

return $input.all().map((item) => {
  const b = item.json;
  const seed = b.isSeedRun === true;

  // Nothing here was actually visited, so the verdict is capped. A name the
  // policy says should NEVER be public still deserves a look; everything else
  // is recorded for the inventory rather than pushed at a human.
  const cap = seed ? 'Expected' : b.exposurePolicy === 'never' ? 'Look soon' : 'Informational';
  const verdict =
    VERDICT_RANK[b.nameVerdict] < VERDICT_RANK[cap] ? b.nameVerdict : cap;

  const signals = seed
    ? ['Recorded from the initial baseline snapshot, not assessed']
    : [...(b.policyNotes || []), 'Not checked this run, so the verdict is capped'];

  return {
    json: {
      first_seen: b.detectedAt,
      apex: b.apex,
      hostname: b.hostname,
      verdict,
      why: seed
        ? 'Already present when the inventory was created'
        : b.policyLabel + ', judged from the hostname alone without visiting it',
      recommended_action: seed
        ? 'None'
        : verdict === 'Look soon'
        ? 'Raise the probe cap or check this host manually'
        : 'None, recorded in the inventory for reference',
      exposure_policy: seed ? 'baseline' : b.exposurePolicy,
      risk_score: seed ? 0 : VERDICT_RANK[verdict] * 25,
      probed: 'no',
      http_status: '',
      server: '',
      page_title: '',
      product_detected: '',
      takeover_service: '',
      analyst: seed ? 'baseline' : 'rules',
      last_checked: checkedAt,
      verdict_rank: seed ? 0 : VERDICT_RANK[verdict],
      signals,
      evidence: { reachable: null },
      policyLabel: b.policyLabel,
    },
  };
});

// Overlay the AI verdicts onto the rules based rows.
// The rules layer is authoritative on escalation: AI can raise a verdict but
// never lower one, so a misbehaving model cannot silence a real finding.
const VERDICT_RANK = { 'Review now': 4, 'Look soon': 3, Informational: 2, Expected: 1 };
const VALID = Object.keys(VERDICT_RANK);

const rows = $('Read Probe Evidence').all().map((i) => i.json);

let findings = [];
try {
  const raw = $input.first().json;
  const parsed = raw.output ?? raw;
  findings = Array.isArray(parsed) ? parsed : parsed.findings || [];
} catch (e) {
  findings = [];
}

const byHost = new Map();
for (const f of findings) {
  if (f && typeof f.hostname === 'string') byHost.set(f.hostname.toLowerCase(), f);
}

return rows.map((row) => {
  const ai = byHost.get(String(row.hostname).toLowerCase());

  if (!ai || !VALID.includes(ai.verdict)) {
    return { json: { ...row, analyst: 'rules' } };
  }

  const aiRank = VERDICT_RANK[ai.verdict];
  const ruleRank = VERDICT_RANK[row.verdict];

  // The rules layer wins on escalation. If the model tried to soften a
  // finding, keep the rules verdict AND the rules wording: an explanation
  // that argues the opposite of its own verdict is worse than none.
  const downgraded = aiRank < ruleRank;
  const verdict = downgraded ? row.verdict : ai.verdict;

  const why = downgraded ? row.why : String(ai.why || row.why).slice(0, 300);
  const action = downgraded
    ? row.recommended_action
    : String(ai.action || row.recommended_action).slice(0, 300);
  const product = row.product_detected || String(ai.product || '').slice(0, 60);

  const signals = [...row.signals];
  if (ai.confidence && ai.confidence !== 'high') {
    signals.push('AI confidence: ' + ai.confidence);
  }
  if (aiRank > ruleRank) {
    signals.push('Raised from "' + row.verdict + '" by the AI analyst');
  }
  if (downgraded) {
    signals.push('AI proposed "' + ai.verdict + '" but the policy rules hold, so it was kept');
  }

  return {
    json: {
      ...row,
      verdict,
      why,
      recommended_action: action,
      product_detected: product,
      risk_score: VERDICT_RANK[verdict] * 25 - (row.evidence.reachable ? 0 : 10),
      verdict_rank: VERDICT_RANK[verdict],
      analyst: downgraded ? 'rules (ai overruled)' : 'ai',
      signals,
    },
  };
});

// Build the Slack Block Kit message and the HTML email.
// Findings are grouped by category rather than listed one box per hostname,
// and both channels open with what this report is and what is being asked.
const cfg = $('Configuration').first().json;

// Everything at or above the alert threshold. The Filter has alwaysOutputData
// on, so a run with nothing to alert arrives as a single empty item: drop it.
const findings = $input
  .all()
  .map((i) => i.json)
  .filter((f) => f && f.hostname);

// Every new hostname this run, including the ones that did not clear the
// threshold. Those still belong in the report, listed but not demanded.
const everything = $('Combine All New Hostnames')
  .all()
  .map((i) => i.json)
  .filter((r) => r && r.hostname);

// The first run seeds the whole inventory. Stay silent.
if (everything.length && everything.every((r) => r.exposure_policy === 'baseline')) return [];

// Nothing new at all: say nothing.
if (everything.length === 0 && findings.length === 0) return [];

const alertingHosts = new Set(findings.map((f) => String(f.hostname).toLowerCase()));
const recorded = everything.filter(
  (r) => !alertingHosts.has(String(r.hostname).toLowerCase())
);

const allNew = everything.length;
const probedCount = $('Rank and Flag Probe Queue')
  .all()
  .filter((i) => i.json.willProbe === true).length;
const recordedOnly = recorded.length;

const STYLE = {
  'Review now': { emoji: ':red_circle:', color: '#b91c1c', order: 1 },
  'Look soon': { emoji: ':large_orange_circle:', color: '#ea580c', order: 2 },
  Informational: { emoji: ':large_blue_circle:', color: '#2563eb', order: 3 },
  Expected: { emoji: ':white_circle:', color: '#64748b', order: 4 },
};

// How many to show in full before pointing at the sheet.
// Every hostname is listed. These only control how much detail each one gets,
// never whether it appears at all.
const MAX_DETAIL = 12;       // "Review now" entries shown as full cards
const MAX_SLACK_DETAIL = 6;  // "Review now" full sections in Slack
const SLACK_BLOCK_BUDGET = 46; // Slack hard limit is 50
const SLACK_TEXT_LIMIT = 2800; // Slack hard limit is 3000 per section
const EMAIL_NAME_BUDGET = 1000; // Gmail clips a message at ~102KB

findings.sort(
  (a, b) =>
    (STYLE[a.verdict]?.order ?? 9) - (STYLE[b.verdict]?.order ?? 9) ||
    b.risk_score - a.risk_score
);

const reviewNow = findings.filter((f) => f.verdict === 'Review now');
const lookSoon = findings.filter((f) => f.verdict === 'Look soon');
const nothingToAct = reviewNow.length === 0 && lookSoon.length === 0;

// Group a list of findings by their policy category.
function groupByCategory(list) {
  const map = new Map();
  for (const f of list) {
    const key = f.policyLabel || 'Unrecognized name';
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(f);
  }
  return [...map.entries()].sort((a, b) => b[1].length - a[1].length);
}

const lookSoonGroups = groupByCategory(lookSoon);
const recordedGroups = groupByCategory(recorded);

const takeovers = findings.filter((f) => f.takeover_service);
const aiUsed = findings.some((f) => f.analyst === 'ai');
const runDate = new Date().toISOString().slice(0, 10);
const top = findings[0] || { verdict: 'Informational' };

const subject = nothingToAct
  ? '[Recorded] Attack surface: ' + allNew + ' new hostname' + (allNew === 1 ? '' : 's') +
    ', none need action on ' + runDate
  : '[' + top.verdict + '] Attack surface: ' +
  (reviewNow.length ? reviewNow.length + ' to review now, ' : '') +
  lookSoon.length + ' to look at on ' + runDate;

const sheetUrl = cfg.sheetId
  ? 'https://docs.google.com/spreadsheets/d/' + cfg.sheetId
  : '';

function evidenceLine(f, withProduct) {
  if (f.probed !== 'yes') return 'not checked this run';
  if (f.evidence && f.evidence.reachable === false) return 'no HTTPS response';
  return (
    'HTTP ' + f.http_status +
    (withProduct && f.product_detected ? ' · ' + f.product_detected : '')
  );
}

// Pack hostnames into as many Slack sections as it takes. Slack caps a section
// at 3000 characters, so long lists are split rather than cut.
function nameSections(heading, names) {
  const out = [];
  let cur = heading;
  let first = true;

  for (const n of names) {
    const piece = (first ? '' : '  ') + '`' + n + '`';
    if (cur.length + piece.length > SLACK_TEXT_LIMIT) {
      out.push(cur);
      cur = '`' + n + '`';
    } else {
      cur += piece;
      first = false;
    }
  }
  if (cur.trim()) out.push(cur);
  return out;
}

let slackTruncated = 0;
function pushNameSections(blocks, heading, names) {
  for (const text of nameSections(heading, names)) {
    if (blocks.length >= SLACK_BLOCK_BUDGET) {
      slackTruncated += names.length;
      return;
    }
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text } });
  }
}

// ============================================================== Slack blocks
const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: 'New subdomains found on your domains', emoji: true },
  },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text:
          'Public certificate logs showed *' + allNew + '* hostname' + (allNew === 1 ? '' : 's') +
          " that weren't in your inventory. *" + probedCount + '* were checked over HTTPS' +
          (aiUsed ? ', then reviewed by an AI analyst' : '') + '.',
      },
    ],
  },
];

const ask = [];
if (reviewNow.length) {
  ask.push(':red_circle: *' + reviewNow.length + ' to review now* — confirm each is meant to be public, restrict it today if not.');
}
if (lookSoon.length) {
  ask.push(':large_orange_circle: *' + lookSoon.length + ' to look at* — find the owner and confirm the exposure is intentional.');
}
if (recordedOnly) {
  ask.push(':white_circle: *' + recordedOnly + ' recorded only* — no action needed, they are in the sheet.');
}
if (nothingToAct) {
  ask.push('_Nothing crossed your alert threshold this run. This is a record, not a call to act._');
}
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ask.join('\n') } });
blocks.push({ type: 'divider' });

if (reviewNow.length) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: ':red_circle: *Review now*' },
  });

  for (const f of reviewNow.slice(0, MAX_SLACK_DETAIL)) {
    blocks.push({
      type: 'section',
      text: {
        type: 'mrkdwn',
        text:
          '`' + f.hostname + '`  _(' + evidenceLine(f) + ')_\n' +
          f.why + '\n:arrow_right: ' + f.recommended_action +
          (f.takeover_service
            ? '\n:rotating_light: Dangling *' + f.takeover_service + '* response, possible subdomain takeover'
            : ''),
      },
    });
  }

  // The rest are still named, just without the full write-up.
  if (reviewNow.length > MAX_SLACK_DETAIL) {
    pushNameSections(
      blocks,
      '_Also review now, details in the email:_\n',
      reviewNow.slice(MAX_SLACK_DETAIL).map((f) => f.hostname)
    );
  }
}

if (lookSoonGroups.length) {
  blocks.push({ type: 'divider' });
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: ':large_orange_circle: *Worth a look, grouped by what they appear to be*' },
  });

  for (const [category, list] of lookSoonGroups) {
    // Small groups keep the per-host evidence; large ones pack inline so that
    // every name still fits.
    if (list.length <= 8) {
      const lines = list
        .map((f) => '• `' + f.hostname + '` _(' + evidenceLine(f, true) + ')_')
        .join('\n');
      if (blocks.length < SLACK_BLOCK_BUDGET) {
        blocks.push({
          type: 'section',
          text: { type: 'mrkdwn', text: '*' + category + '* (' + list.length + ')\n' + lines },
        });
      }
    } else {
      pushNameSections(
        blocks,
        '*' + category + '* (' + list.length + ')\n',
        list.map((f) => f.hostname)
      );
    }
  }
}

if (recordedGroups.length) {
  blocks.push({ type: 'divider' });
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: ':white_circle: *Also new, no action needed* (' + recorded.length + ')',
    },
  });

  for (const [category, list] of recordedGroups) {
    pushNameSections(
      blocks,
      '*' + category + '* (' + list.length + ')\n',
      list.map((f) => f.hostname)
    );
  }

  if (slackTruncated) {
    blocks.push({
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text:
            'Slack caps a message at 50 blocks, so ' + slackTruncated +
            ' name(s) did not fit here. Every one of them is in the email and the sheet.',
        },
      ],
    });
  }
}

blocks.push({
  type: 'context',
  elements: [
    {
      type: 'mrkdwn',
      text: 'If a name is normal for you, add its prefix to `expectedPrefixes` in the workflow so it stops appearing.',
    },
  ],
});

if (sheetUrl) {
  blocks.push({
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Open the full inventory', emoji: true },
        url: sheetUrl,
        style: 'primary',
      },
    ],
  });
}

const slackBlocks = { blocks };

// ===================================================================== Email
const FONT = 'font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Helvetica,Arial,sans-serif';

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function chip(v) {
  const c = (STYLE[v] || STYLE.Informational).color;
  return (
    '<span style="display:inline-block;background:' + c +
    ';color:#ffffff;border-radius:4px;padding:3px 10px;' + FONT +
    ';font-size:11px;font-weight:700;letter-spacing:0.4px;text-transform:uppercase;">' +
    esc(v) + '</span>'
  );
}

function sectionHeading(text, color) {
  return (
    '<tr><td style="padding:22px 18px 8px 18px;border-top:1px solid #e2e8f0;">' +
    '<div style="' + FONT + ';font-size:15px;font-weight:800;color:' + color + ';">' +
    esc(text) + '</div></td></tr>'
  );
}

// --- one full detail card, used for "Review now" only ----------------------
function detailCard(f) {
  // Product, evidence line and page title often say the same thing. Dedupe.
  const seen = new Set();
  const meta = [];
  const addMeta = (raw, html) => {
    const key = String(raw || '').trim().toLowerCase();
    if (!key || seen.has(key)) return;
    seen.add(key);
    meta.push(html);
  };

  addMeta(f.product_detected, '<strong>' + esc(f.product_detected) + '</strong>');
  addMeta(evidenceLine(f), esc(evidenceLine(f)));
  addMeta(f.server, esc(f.server));
  addMeta(f.page_title, esc(f.page_title));

  return (
    '<tr><td style="padding:12px 18px;border-bottom:1px solid #f1f5f9;">' +
    '<div style="' + FONT + ';font-size:15px;font-weight:700;color:#0f172a;word-break:break-all;">' +
    esc(f.hostname) +
    (f.analyst === 'ai'
      ? '<span style="font-size:11px;font-weight:400;color:#94a3b8;padding-left:8px;">AI reviewed</span>'
      : '') +
    '</div>' +
    '<div style="' + FONT + ';font-size:14px;line-height:1.6;color:#334155;padding-top:5px;">' +
    esc(f.why) + '</div>' +
    '<div style="' + FONT + ';font-size:12px;color:#64748b;padding-top:5px;">' + meta.join(' &nbsp;·&nbsp; ') + '</div>' +
    '<div style="' + FONT + ';font-size:13px;color:#0f172a;padding-top:8px;">&rarr; ' +
    esc(f.recommended_action) + '</div>' +
    (f.takeover_service
      ? '<div style="' + FONT + ';font-size:12px;color:#b91c1c;font-weight:700;padding-top:6px;">' +
        'Dangling ' + esc(f.takeover_service) + ' response, possible subdomain takeover</div>'
      : '') +
    '</td></tr>'
  );
}

// --- one compact category block -------------------------------------------
function categoryBlock(category, list) {
  const names = list
    .map(
      (f) =>
        '<div style="' + FONT + ';font-size:13px;line-height:1.9;color:#334155;">' +
        '<span style="font-weight:600;word-break:break-all;">' + esc(f.hostname) + '</span>' +
        '<span style="color:#94a3b8;"> &nbsp;' + esc(evidenceLine(f)) + '</span></div>'
    )
    .join('');

  const extra = '';

  return (
    '<tr><td style="padding:10px 18px;border-bottom:1px solid #f1f5f9;">' +
    '<div style="' + FONT + ';font-size:13px;font-weight:800;color:#0f172a;padding-bottom:6px;">' +
    esc(category) + ' <span style="color:#94a3b8;font-weight:600;">(' + list.length + ')</span></div>' +
    names + extra +
    '</td></tr>'
  );
}

let emailNameBudget = EMAIL_NAME_BUDGET;
let emailNamesOmitted = 0;

// A dense block for long lists: every hostname, wrapped inline rather than one
// per line, so nothing has to be cut.
function compactCategoryBlock(category, list) {
  const unchecked = list.filter((f) => f.probed !== 'yes').length;
  const note =
    unchecked === list.length
      ? 'none checked this run'
      : unchecked
      ? unchecked + ' of ' + list.length + ' not checked this run'
      : 'all checked';

  // Plain wrapped text rather than a styled chip per name: at several hundred
  // hostnames the chip markup alone pushes the email past Gmail's 102KB clip.
  // Gmail silently clips past ~102KB, which would cut the footer and the
  // inventory link. Spend the name budget, then say plainly what was left out.
  const shown = list.slice(0, Math.max(0, emailNameBudget));
  emailNameBudget -= shown.length;
  emailNamesOmitted += list.length - shown.length;

  const names =
    '<div style="' + FONT + ';font-size:12px;line-height:1.9;color:#334155;word-break:break-all;">' +
    shown.map((f) => esc(f.hostname)).join(' &nbsp;·&nbsp; ') +
    '</div>';

  return (
    '<tr><td style="padding:10px 18px;border-bottom:1px solid #f1f5f9;">' +
    '<div style="' + FONT + ';font-size:13px;font-weight:800;color:#0f172a;padding-bottom:8px;">' +
    esc(category) + ' <span style="color:#94a3b8;font-weight:600;">(' + list.length +
    ', ' + note + ')</span></div>' +
    names +
    '</td></tr>'
  );
}

let body = '';

if (reviewNow.length) {
  body += sectionHeading('Review now (' + reviewNow.length + ')', '#b91c1c');
  body += reviewNow.slice(0, MAX_DETAIL).map(detailCard).join('');
  if (reviewNow.length > MAX_DETAIL) {
    body += compactCategoryBlock(
      'Also review now, same guidance applies',
      reviewNow.slice(MAX_DETAIL)
    );
  }
}

if (lookSoonGroups.length) {
  body += sectionHeading('Worth a look (' + lookSoon.length + ')', '#ea580c');
  body +=
    '<tr><td style="padding:0 18px 8px 18px;' + FONT + ';font-size:12px;color:#64748b;">' +
    'Grouped by what the hostname and its response suggest it is.</td></tr>';
  body += lookSoonGroups.map(([c, l]) => categoryBlock(c, l)).join('');
}

if (recordedGroups.length) {
  body += sectionHeading('Also new, no action needed (' + recorded.length + ')', '#2563eb');
  body +=
    '<tr><td style="padding:0 18px 8px 18px;' + FONT + ';font-size:12px;color:#64748b;">' +
    'These appeared in certificate transparency too. They did not clear your alert level, ' +
    'either because the name looks ordinary or because they were not checked this run. ' +
    'Every one is listed below and in the sheet.</td></tr>';
  body += recordedGroups.map(([c, l]) => compactCategoryBlock(c, l)).join('');

  if (emailNamesOmitted) {
    body +=
      '<tr><td style="padding:10px 18px 14px 18px;' + FONT + ';font-size:12px;color:#94a3b8;">' +
      emailNamesOmitted + ' further name(s) are not listed here, because the message would ' +
      'otherwise be cut short by your mail client. All of them are in the sheet.</td></tr>';
  }
}

const askRows = [];
if (reviewNow.length) {
  askRows.push(
    '<strong style="color:#b91c1c;">' + reviewNow.length + ' to review now.</strong> ' +
    'Confirm each one is meant to be public. If it is not, put it behind SSO or the VPN today.'
  );
}
if (lookSoon.length) {
  askRows.push(
    '<strong style="color:#ea580c;">' + lookSoon.length + ' to look at.</strong> ' +
    'Identify the owner and confirm the exposure is intentional.'
  );
}
if (recordedOnly) {
  askRows.push(
    '<strong style="color:#64748b;">' + recordedOnly + ' recorded only.</strong> ' +
    'No action needed. They are in the sheet if you want them.'
  );
}

if (nothingToAct) {
  askRows.push(
    'Nothing crossed your alert threshold this run. This is a record of what appeared, not a call to act.'
  );
}

const html =
  '<div style="background:#f1f5f9;padding:24px 0;">' +
  '<table role="presentation" width="660" cellpadding="0" cellspacing="0" border="0" ' +
  'style="width:100%;max-width:660px;margin:0 auto;background:#ffffff;border-radius:10px;overflow:hidden;">' +

  '<tr><td style="background:' + (STYLE[top.verdict] || STYLE.Informational).color + ';height:5px;"></td></tr>' +

  // ---- title
  '<tr><td style="padding:24px 18px 4px 18px;">' +
  '<div style="' + FONT + ';font-size:20px;font-weight:800;color:#0f172a;">New subdomains found on your domains</div>' +
  '<div style="' + FONT + ';font-size:13px;color:#64748b;padding-top:6px;">' + runDate +
  ' &nbsp;·&nbsp; ' + esc(String(cfg.apexDomains || '')) + '</div>' +
  '</td></tr>' +

  // ---- what this is
  '<tr><td style="padding:14px 18px 6px 18px;">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" ' +
  'style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;">' +
  '<tr><td style="padding:16px 18px;">' +
  '<div style="' + FONT + ';font-size:13px;font-weight:800;color:#0f172a;padding-bottom:8px;">What this is</div>' +
  '<div style="' + FONT + ';font-size:13px;line-height:1.75;color:#334155;">' +
  'Every TLS certificate issued for your domains is published to public Certificate Transparency logs, ' +
  'which means anyone can see the hostnames your teams create. This report lists the ones that appeared ' +
  'there since the last run and were not already in your inventory sheet.<br><br>' +
  '<strong>' + allNew + '</strong> new hostname(s) were found. <strong>' + probedCount + '</strong> of them were ' +
  'visited once over HTTPS to see what is actually running' + (aiUsed ? ', then reviewed by an AI analyst' : '') + '.' +
  '</div></td></tr></table></td></tr>' +

  // ---- what is being asked
  '<tr><td style="padding:10px 18px 6px 18px;">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" ' +
  'style="background:#ffffff;border:1px solid #e2e8f0;border-radius:8px;">' +
  '<tr><td style="padding:16px 18px;">' +
  '<div style="' + FONT + ';font-size:13px;font-weight:800;color:#0f172a;padding-bottom:8px;">What we need from you</div>' +
  askRows
    .map(
      (r) =>
        '<div style="' + FONT + ';font-size:13px;line-height:1.7;color:#334155;padding-bottom:6px;">' + r + '</div>'
    )
    .join('') +
  (takeovers.length
    ? '<div style="' + FONT + ';font-size:13px;line-height:1.7;color:#b91c1c;font-weight:700;padding-top:4px;">' +
      'Start with the ' + takeovers.length + ' pointing at a third party service that no longer serves them. ' +
      'Those can be claimed by someone else.</div>'
    : '') +
  '</td></tr></table></td></tr>' +

  // ---- findings
  '<tr><td style="padding:8px 0 0 0;"><table role="presentation" width="100%" cellpadding="0" ' +
  'cellspacing="0" border="0">' + body + '</table></td></tr>' +

  // ---- footer
  (sheetUrl
    ? '<tr><td style="padding:20px 18px 8px 18px;"><a href="' + sheetUrl +
      '" style="display:inline-block;background:#0f172a;color:#ffffff;text-decoration:none;' +
      'border-radius:6px;padding:11px 22px;' + FONT + ';font-size:14px;font-weight:600;">' +
      'Open the full inventory</a></td></tr>'
    : '') +
  '<tr><td style="padding:8px 18px 18px 18px;' + FONT + ';font-size:11px;line-height:1.7;color:#94a3b8;">' +
  'If a hostname here is normal for your organization, add its prefix to <strong>expectedPrefixes</strong> ' +
  'in the workflow and it will stop being reported.<br><br>' +
  'Source: crt.name passive subdomain index, built from public certificate transparency logs. ' +
  'Verdicts come from your exposure policy table plus one unauthenticated HTTPS request' +
  (aiUsed ? ', reviewed by an AI analyst' : '') + '. ' +
  'Response bodies are discarded after matching and are never written to the sheet or this report.' +
  '</td></tr></table></div>';

return [
  {
    json: {
      subject,
      html,
      slackBlocks,
      slackChannel: String(cfg.slackChannel || '#security-alerts'),
      summary: {
        runDate,
        newHostnames: allNew,
        probed: probedCount,
        reviewNow: reviewNow.length,
        lookSoon: lookSoon.length,
        recordedOnly,
        nothingToAct,
        emailNamesOmitted,
        takeoverCandidates: takeovers.length,
        aiUsed,
      },
    },
  },
];
